/**
 * Runtime microapp configuration.
 *
 * In Docker: this file is OVERWRITTEN by docker-entrypoint.sh at container
 * startup using the MESH_POLLS_URL and MESH_WHITEBOARD_URL
 * environment variables. Do not edit this file manually in production.
 *
 * In local dev: default to localhost widget URLs when running on localhost or
 * 127.0.0.1, while still allowing Docker to replace this entire file.
 */
(function () {
  var isLocalhost =
    window.location.hostname === 'localhost' ||
    window.location.hostname === '127.0.0.1';

  window.__MESH_MICROAPPS__ = {
    pollsWidgetUrl: isLocalhost ? 'http://localhost:3001' : '',
    whiteboardWidgetUrl: isLocalhost ? 'http://localhost:3003' : '',
  };
})();
